import{z as t,x as s,o as e,c as i,q as m,j as r,D as o,d as l,s as B,S as c,b as E}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"vmalloc","description":"","frontmatter":{"title":"vmalloc","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/vmalloc.md","filePath":"cs/vmalloc.md","lastUpdated":1791063341000}'),n={name:"cs/vmalloc.md"};function d(p,a,v,u,D,h){const A=s("Mermaid");return e(),i("div",null,[a[2]||(a[2]=m('<h1 id="vmalloc" tabindex="-1">vmalloc <a class="header-anchor" href="#vmalloc" aria-label="Permalink to &quot;vmalloc&quot;">​</a></h1><div class="epigraph"><p>vmalloc 在内核虚空间找一段连续虚址，背后可以是不连续的页框，用来放下大缓冲而不要求 buddy 高阶成功。</p><footer>—— 据 Gorman 对 vmalloc 的说明；Linux vmalloc 文档</footer></div><p><a href="/cs/memory-hotplug">热插拔</a> 与 <a href="/cs/page-migration-compaction">compaction</a> 都在为<strong>物理连续</strong>奋斗。内核有时只需<strong>虚连续</strong>。缺口是 vmalloc：模块、大数组、<a href="/cs/xdp-ebpf">BPF</a> 映像。不是用户 <code>malloc</code>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>kmalloc</code> 要 physically contiguous，大了易失败。<a href="/cs/buddy-allocator">buddy</a> 高阶依赖反碎片。vmalloc：分配 N 个单页，装进内核页表一段连续 VA。缺口：TLB 效率差（多页）、持锁、不能用于某些 DMA（除非再映射）；<code>vmap</code> 已有页。本课不把 ioremap 的全部缓存属性写完，只点亲戚。</p><p><span class="marginnote">术语翻译：「虚连续」是 CPU 视角地址连成一片，「物理连续」是内存条视角页框挨在一起；vmalloc 用页表把两者解耦——地址上像一块整砖，物理上是散落的碎砖，每次访存查一下页表就拼回整块。</span></p><p><span class="marginnote">vmalloc 区在 64 位很大。原子上下文不能睡的路径不能 vmalloc。模块加载走这。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>vmalloc</code>：取虚区，alloc_page 循环，建立 pte。<code>vfree</code> 拆表还页。对照用户 mmap：都是虚连续物理可散；内核没有缺页处理同一套，通常预填。对照 <a href="/cs/thp">THP</a>：vmalloc 一般 4K。</p><p><span class="marginnote">数字实例：要 1MB 缓冲，kmalloc 需要 256 张 4KB 页恰好物理连续（buddy 的 8 阶块），碎片化的机器上这一单常常失败；vmalloc 只要 256 张任意单页加 256 条页表项，几乎总能成功——用建表与查表的开销，换回成功率。</span></p>',10)),(e(),r(c,null,{default:o(()=>[B(A,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20REQ%5B%22%E5%86%85%E6%A0%B8%E8%A6%81%E5%A4%A7%E7%BC%93%E5%86%B2%22%5D%20--%3E%20VA%5B%22%E8%BF%9E%E7%BB%AD%E5%86%85%E6%A0%B8%E8%99%9A%E5%9D%80%22%5D%0A%20%20VA%20--%3E%20PAGES%5B%22%E5%A4%9A%E5%BC%A0%E5%8F%AF%E8%83%BD%E4%B8%8D%E8%BF%9E%E7%BB%AD%E7%9A%84%E9%A1%B5%22%5D%0A%20%20PAGES%20--%3E%20PTE%5B%22%E5%86%85%E6%A0%B8%E9%A1%B5%E8%A1%A8%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[l("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"vmalloc 用页表换「不必物理连续」，使内核在碎片化机器上仍能加载模块。代价是建立慢、访问可能更多 TLB miss。不要写成用户堆实现——那是后课 malloc。与 rmap：内核映射通常不走 anon_vma。",-1)),a[5]||(a[5]=E("p",null,[l("错误：把 vmalloc 地址传给只能 DMA 物理连续的设备会错，要用 bounce 或 "),E("code",null,"vmalloc_to_page"),l(" 逐页。")],-1)),(e(),r(c,null,{default:o(()=>[B(A,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20NEED%5B%22%E5%86%85%E6%A0%B8%E8%A6%81%E4%B8%80%E6%AE%B5%E5%86%85%E5%AD%98%22%5D%20--%3E%20SIZE%7B%22%E5%A4%9A%E5%A4%A7%2C%20%E8%A6%81%E4%BB%80%E4%B9%88%E8%BF%9E%E7%BB%AD%22%7D%0A%20%20SIZE%20--%3E%7C%22%E5%B0%8F%E4%B8%94%E8%A6%81%E7%89%A9%E7%90%86%E8%BF%9E%E7%BB%AD%22%7C%20KM%5B%22kmalloc%3A%20buddy%20%E9%AB%98%E9%98%B6%E5%9D%97%22%5D%0A%20%20SIZE%20--%3E%7C%22%E5%A4%A7%E4%B8%94%E5%8F%AA%E9%9C%80%E8%99%9A%E8%BF%9E%E7%BB%AD%22%7C%20VM%5B%22vmalloc%3A%20%E9%80%90%E9%A1%B5%E6%8B%BC%E8%A3%85%E5%8A%A0%E9%A1%B5%E8%A1%A8%22%5D%0A%20%20KM%20--%3E%20OK%5B%22DMA%20%E4%B8%8E%E7%A1%AC%E4%BB%B6%E5%8F%AF%E7%9B%B4%E6%8E%A5%E4%BD%BF%E7%94%A8%22%5D%0A%20%20VM%20--%3E%20TLB%5B%22%E4%BB%A3%E4%BB%B7%3A%20%E5%BB%BA%E8%A1%A8%E6%85%A2%2C%20TLB%20miss%20%E5%81%8F%E5%A4%9A%22%5D%0A%20%20VM%20--%3E%20DMACARE%7B%22%E8%A6%81%E4%BA%A4%E7%BB%99%E8%AE%BE%E5%A4%87%20DMA%20%E5%90%97%22%7D%0A%20%20DMACARE%20--%3E%7C%22%E7%9B%B4%E6%8E%A5%E4%BC%A0%20vmalloc%20%E5%9C%B0%E5%9D%80%22%7C%20WRONG%5B%22%E9%94%99%E8%AF%AF%3A%20%E8%AE%BE%E5%A4%87%E7%9C%8B%E5%88%B0%E7%9A%84%E6%98%AF%E6%95%A3%E9%A1%B5%22%5D%0A%20%20DMACARE%20--%3E%7C%22vmalloc_to_page%20%E9%80%90%E9%A1%B5%E6%98%A0%E5%B0%84%22%7C%20RIGHT%5B%22%E6%AD%A3%E7%A1%AE%22%5D%0A"})]),fallback:o(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=m('<p><span class="marginnote">常见误区：在中断处理这类不能睡眠的上下文里调 vmalloc。分配页时可能要等内存回收，一睡就把原子上下文炸了——那类路径只能用预先分配好的池子，或改用带原子标志的 kmalloc。</span></p><p>实现上：频繁 vmalloc/vfree 会打碎内核虚空间并伤 TLB。vmap 已有页用于模块或图形缓冲。原子上下文只能用预分配，不能睡着等页。 读法上只引用<a href="/cs/memory-hotplug">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「内存进阶 / 回收、迁移与加固」课序里，对象是 <strong>vmalloc</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 vmap 栈的 hardened 配置全文。不保证实时延迟。下一课对照：直接映射与高端内存为何存在。</p><p>版本字段会变，课序钉的是机制对象「vmalloc」，不是某一主线内核的结构体名。 后课默认：内核可用 vmalloc 得虚连续。线性映射与 HIGHMEM，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>vmalloc：虚连续、物理可散。</li><li>kmalloc：物理连续，大分配易失败。</li><li>直接映射与 highmem 是下一课。</li><li>出处：Gorman；Linux mm/vmalloc.c 文档；<em>ULK</em>。</li></ul>',9))])}const C=t(n,[["render",d]]);export{_ as __pageData,C as default};
